tiles = {
  9: [[1,0,1],[1,1,1],[0,1,0]],
  6: [[0,1,1],[0,1,1],[1,0,0]],
  3: [[1,0,1],[0,1,1],[0,1,0]],
  4: [[1,1,1],[0,1,0],[0,1,0]],
}
# Build 2x2 five-by-five tiles with one-cell 2 separators and outer margin.
out = [[2]*13 for _ in range(13)]
for block_row, colors in enumerate(((9,6),(3,4))):
    r0 = 1 + block_row*6
    for block_col, color in enumerate(colors):
        c0 = 1 + block_col*6
        for r in range(5):
            for c in range(5):
                out[r0+r][c0+c] = color
        for r in range(3):
            for c in range(3):
                if tiles[color][r][c]:
                    out[r0+1+r][c0+1+c] = 2
assert len(out)==13 and all(len(row)==13 for row in out)
print(out)
